"""Fresh CPU replay of verbatim tests generated by the historical real 14B run."""
import hashlib
import json
import os
from pathlib import Path
import platform
import subprocess
import sys
import time
import argparse

ROOT=Path(__file__).resolve().parents[1]


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output',type=Path,default=ROOT/'research/14b_application_replay_20261119')
    args=parser.parse_args()
    source=ROOT/'research/application/14b_genty_curated_20261117'
    manifest=json.loads((source/'manifest.json').read_text())
    subject=ROOT/'local_benchmark_repos/genty'
    out=args.output.resolve()
    out.mkdir(exist_ok=False)
    h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
    for name,value in manifest['production_sha256'].items():
        if h(subject/name)!=value:raise RuntimeError('Pinned source mismatch')
    testdir=out/'tests';testdir.mkdir()
    for name,value in manifest['files_sha256'].items():
        if h(source/name)!=value:raise RuntimeError('Test artifact mismatch')
        (testdir/name).write_bytes((source/name).read_bytes())
    results=[]
    for i in range(3):
        dest=out/('replay'+str(i+1));dest.mkdir()
        env={'PATH':os.environ['PATH'],'PYTHONPATH':str(subject),'HOME':str(dest),
             'PYTHONDONTWRITEBYTECODE':'1','PYTEST_DISABLE_PLUGIN_AUTOLOAD':'1','LANG':'C.UTF-8'}
        cmd=[sys.executable,'-m','pytest','-q','-o','addopts=',
             '--confcutdir='+str(testdir),'-p','pytest_jsonreport.plugin','--json-report',
             '--json-report-file='+str(dest/'pytest.json'),str(testdir)]
        started=time.monotonic();p=subprocess.run(cmd,cwd=subject,env=env,capture_output=True,text=True,timeout=20)
        elapsed=time.monotonic()-started;(dest/'stdout.txt').write_text(p.stdout);(dest/'stderr.txt').write_text(p.stderr)
        report=json.loads((dest/'pytest.json').read_text())
        result=dict(returncode=p.returncode,seconds=elapsed,total=len(report.get('tests',[])),
                    passed=sum(t['outcome']=='passed' for t in report.get('tests',[])),
                    nodeids=sorted(t['nodeid'].split('::',1)[-1] for t in report.get('tests',[])))
        (dest/'process.json').write_text(json.dumps(result,indent=2));results.append(result)
    summary=dict(kind='Fresh CPU replay of selected real 14B-generated baseline artifacts; no inference',
        origin_manifest_sha256=h(source/'manifest.json'),original_model='Qwen2.5-Coder-14B-Instruct NF4',
        origin_model_execution='Kaggle Dual T4; historical warm-prefix baseline',
        python=platform.python_version(),test_files_sha256=manifest['files_sha256'],
        source_files_sha256=manifest['production_sha256'],replays=results,
        identical_node_sets=all(r['nodeids']==results[0]['nodeids'] for r in results),
        caveats=['Selected application subset, not representative efficacy.',
                 'Fresh CPU/Python runtime differs from original GPU generation runtime.',
                 'Replay timing excludes model generation, installation and original cold initialization.'])
    (out/'summary.json').write_text(json.dumps(summary,indent=2))
    assert all(r['returncode']==0 and r['passed']==r['total']==12 for r in results)
    print(json.dumps({'replays':3,'nodes_per_replay':12,'seconds':[r['seconds'] for r in results],'model_inference':False}))


if __name__=='__main__':main()
